CREATE TABLE pitches(game_id BIGINT, at_bat_number INTEGER, pitch_number INTEGER, pitcher_id BIGINT, game_date DATE NOT NULL, batter_id BIGINT, inning INTEGER, inning_topbot VARCHAR, stand VARCHAR, p_throws VARCHAR, balls INTEGER, strikes INTEGER, pitch_type VARCHAR, description VARCHAR, events VARCHAR, pitch_result VARCHAR, release_speed DOUBLE, effective_speed DOUBLE, release_pos_x DOUBLE, release_pos_y DOUBLE, release_pos_z DOUBLE, release_extension DOUBLE, arm_angle DOUBLE, release_spin_rate DOUBLE, pfx_x DOUBLE, pfx_z DOUBLE, spin_axis DOUBLE, plate_x DOUBLE, plate_z DOUBLE, sz_top DOUBLE, sz_bot DOUBLE, "zone" INTEGER, outs_when_up INTEGER, api_break_z_with_gravity DOUBLE, is_hbp BOOLEAN, is_actual_pitch BOOLEAN, quality_flags VARCHAR, raw_json JSON NOT NULL, FOREIGN KEY (game_id) REFERENCES games(game_id), FOREIGN KEY (pitcher_id) REFERENCES pitchers(pitcher_id), PRIMARY KEY(game_id, at_bat_number, pitch_number));

