CREATE TABLE roster_snapshots(team_id BIGINT, snapshot_date DATE, player_id BIGINT, player_name VARCHAR, "position" VARCHAR, status VARCHAR, raw_json JSON, FOREIGN KEY (team_id) REFERENCES teams(team_id), PRIMARY KEY(team_id, snapshot_date, player_id));

