CREATE TABLE teams(team_id BIGINT PRIMARY KEY, team_name VARCHAR, abbreviation VARCHAR, raw_json JSON, retrieved_at TIMESTAMP);

CREATE TABLE team_seasons(team_id BIGINT, season INTEGER, team_name VARCHAR, abbreviation VARCHAR, raw_json JSON, retrieved_at TIMESTAMP, FOREIGN KEY (team_id) REFERENCES teams(team_id), PRIMARY KEY(team_id, season));

CREATE TABLE transactions(transaction_id BIGINT PRIMARY KEY, player_id BIGINT, player_name VARCHAR, transaction_date DATE, effective_date DATE, resolution_date DATE, from_team_id BIGINT, to_team_id BIGINT, type_code VARCHAR, type_description VARCHAR, description VARCHAR, is_il_placement BOOLEAN, is_il_activation BOOLEAN, is_elbow_related BOOLEAN, raw_json JSON, source_url VARCHAR);

CREATE TABLE workload_features(game_id BIGINT, pitcher_id BIGINT, workload_max_date TIMESTAMP_NS, rest_days DOUBLE, workload_history_appearances BIGINT, pitches_prev_7d BIGINT, pitches_7d BIGINT, innings_prev_7d DOUBLE, innings_7d DOUBLE, appearances_7d BIGINT, workload_7d_complete BOOLEAN, pitches_prev_14d BIGINT, pitches_14d BIGINT, innings_prev_14d DOUBLE, innings_14d DOUBLE, appearances_14d BIGINT, workload_14d_complete BOOLEAN, pitches_prev_28d BIGINT, pitches_28d BIGINT, innings_prev_28d DOUBLE, innings_28d DOUBLE, appearances_28d BIGINT, workload_28d_complete BOOLEAN, starts_prev_30d BIGINT, starter_share_prev_5 DOUBLE, starter_role_prev_5 BOOLEAN, season_pitch_count BIGINT, season_innings DOUBLE, season_appearances BIGINT, season_starts BIGINT, previous_season_innings DOUBLE, current_vs_previous_season_workload DOUBLE, workload_acceleration_7d_vs_21d DOUBLE, acute_chronic_pitch_ratio DOUBLE, appearances_prev_7d BIGINT, appearances_prev_14d BIGINT, appearances_prev_28d BIGINT, PRIMARY KEY(game_id, pitcher_id), FOREIGN KEY (game_id) REFERENCES games(game_id), FOREIGN KEY (pitcher_id) REFERENCES pitchers(pitcher_id));